using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CityNeonWallArtFinish{static CityNeonWallArtFinish(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CityNeonWallArtFinish.request"))return;File.Delete("CityNeonWallArtFinish.request");try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="City Road Facing Neon Wall Art");var material=root.GetComponentInChildren<Renderer>().sharedMaterial;var blocks=new List<Bounds>();foreach(var r in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&!r.transform.IsChildOf(root.transform)&&r.sharedMaterial==material)){var b=r.bounds;b.Expand(2.6f);if(b.size.x<30&&b.size.z<30)blocks.Add(b);}var keepPositions=new List<Vector3>();int removed=0,groups=0;foreach(var f in root.GetComponentsInChildren<MeshFilter>(true)){var mesh=f.sharedMesh;var oldP=mesh.vertices;var oldN=mesh.normals;var oldUV=mesh.uv;var oldC=mesh.colors;var pp=new List<Vector3>();var nn=new List<Vector3>();var uv=new List<Vector2>();var cc=new List<Color>();var ids=new List<int>();for(int k=0;k<oldP.Length;k+=4){var center=Vector3.zero;var b=new Bounds(f.transform.TransformPoint(oldP[k]),Vector3.zero);for(int i=0;i<4;i++){var w=f.transform.TransformPoint(oldP[k+i]);center+=w/4;b.Encapsulate(w);}bool unsafeFace=f.name.ToLower().Contains("building52");if(unsafeFace||blocks.Any(block=>block.Intersects(b))){removed++;continue;}int start=pp.Count;for(int i=0;i<4;i++){pp.Add(oldP[k+i]);nn.Add(oldN[k+i]);uv.Add(oldUV[k+i]);cc.Add(oldC[k+i]);}ids.AddRange(new[]{start,start+1,start+2,start,start+2,start+3});keepPositions.Add(center);}if(pp.Count==0){UnityEngine.Object.DestroyImmediate(f.gameObject);continue;}mesh.Clear();mesh.SetVertices(pp);mesh.SetNormals(nn);mesh.SetUVs(0,uv);mesh.SetColors(cc);mesh.SetTriangles(ids,0);mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);var lod=f.GetComponent<LODGroup>();lod.RecalculateBounds();lod.size=Mathf.Clamp(lod.size,5,14);groups++;}string csv="FinalEnvironmentRoadReview/CityNeonWallArtStrictPlacements.csv";var rows=File.ReadAllLines(csv);File.WriteAllLines(csv,new[]{rows[0]}.Concat(rows.Skip(1).Where(row=>{var a=row.Split(',');var p=new Vector3(float.Parse(a[1]),float.Parse(a[2]),float.Parse(a[3]));return keepPositions.Any(k=>(k-p).sqrMagnitude<.02f);})));PrefabUtility.SaveAsPrefabAsset(root,"Assets/Scenes/Oasis/CityNeonWallArt/Final/City Road Facing Neon Wall Art.prefab");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("FinalEnvironmentRoadReview/CityNeonWallArtFinal.txt","SUCCESS final visual cleanup: removed "+removed+" glass-front / close-to-existing-sign placements. Kept "+keepPositions.Count+" road-facing wall artworks across "+groups+" building groups; "+keepPositions.Count*2+" total triangles. One existing atlas and material, zero new textures/materials/lights/colliders; native city geometry/materials unchanged. Existing texture/shader features retained; shader errors="+ShaderUtil.ShaderHasError(material.shader));}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CityNeonWallArtFinal.txt",e.ToString());Debug.LogException(e);}}}
